# Initially generated by GitHub Copilot.
"""Check for vendoring provenance docs and copy scripts in destination repos.

Results written to out/vendoring_provenance_out.txt.
"""

import sys
from pathlib import Path, PurePosixPath

from vendoring.discover import iter_inventory_seed_rows, provenance_dest_repos

_REPOS = Path(__file__).resolve().parents[3]
_MAM = _REPOS / "MAM-basics"

PROVENANCE_NAMES = [
    "VENDORING.md",
    "vendoring.md",
    "VENDORS.md",
    "vendors.md",
    "vendored-from.md",
    "provenance.md",
    "PROVENANCE.md",
    "shared-with.md",
    "shared-with-MAM-basics.md",
    "copied-from.md",
    "vendored.md",
]

COPY_SCRIPT_PATTERNS = [
    "*copy*py*",
    "*vendor*py*",
    "*sync*py*",
    "*update_pycmn*",
]


def _candidate_scan_dirs_for_repo(repo: str) -> list[str]:
    """Return repo-relative directories to scan for provenance docs.

    Includes repo root (".") and parent directories of discovered vendored
    destination files for the repo, walking up to repo root for each path.
    """
    dirs: set[str] = {"."}
    for data in iter_inventory_seed_rows():
        if data["dest_repo"] != repo:
            continue
        dest_path = PurePosixPath(data["dest_path"])
        current = dest_path.parent if dest_path.suffix else dest_path
        while True:
            dirs.add(str(current))
            if current == PurePosixPath("."):
                break
            current = current.parent

    return sorted(dirs, key=lambda rel: (0 if rel == "." else 1, rel.count("/"), rel))


def _find_provenance_docs(repo: str, repo_path: Path) -> list[str]:
    found_docs: set[str] = set()
    for rel_dir in _candidate_scan_dirs_for_repo(repo):
        scan_dir = repo_path if rel_dir == "." else repo_path / rel_dir
        if not scan_dir.exists():
            continue
        for name in PROVENANCE_NAMES:
            path = scan_dir / name
            if path.exists():
                found_docs.add(str(path.relative_to(_REPOS)))
    return sorted(found_docs)


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8")
    out = _MAM / "out" / "vendoring_provenance_out.txt"
    with out.open("w", encoding="utf-8") as f:
        for repo in provenance_dest_repos():
            repo_path = _REPOS / repo
            f.write(f"\n=== {repo} ===\n")

            # Check for provenance docs
            found_docs = _find_provenance_docs(repo, repo_path)
            if found_docs:
                f.write(f"  PROVENANCE DOCS: {found_docs}\n")
            else:
                f.write("  provenance docs: none\n")

            # Check for copy/sync scripts
            copy_scripts = []
            for pat in COPY_SCRIPT_PATTERNS:
                for hit in repo_path.rglob(pat):
                    if "__pycache__" not in str(hit) and ".venv" not in str(hit):
                        copy_scripts.append(str(hit.relative_to(_REPOS)))
            if copy_scripts:
                f.write(f"  COPY SCRIPTS: {copy_scripts}\n")
            else:
                f.write("  copy scripts: none found\n")

            # List pycmn directory if present at top level or common paths
            for pycmn_rel in ["pycmn", "py/pycmn"]:
                pycmn_path = repo_path / pycmn_rel
                if pycmn_path.exists():
                    files = sorted(
                        p.name
                        for p in pycmn_path.iterdir()
                        if p.suffix == ".py" and p.name != "__init__.py"
                    )
                    f.write(f"  pycmn dir ({pycmn_rel}): {files}\n")

    print(f"Wrote to {out}")
